import{_ as t,o as s,c as a,ag as n}from"./chunks/framework.44aEvdQQ.js";const u=JSON.parse('{"title":"Database Schema Overview","description":"","frontmatter":{},"headers":[],"relativePath":"reference/schema/index.md","filePath":"reference/schema/index.md"}'),r={name:"reference/schema/index.md"};function d(o,e,i,l,p,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="database-schema-overview" tabindex="-1">Database Schema Overview <a class="header-anchor" href="#database-schema-overview" aria-label="Permalink to &quot;Database Schema Overview&quot;">​</a></h1><p>VERA&#39;s database is a Google Sheet with <strong>14 operational tabs</strong> (01–14) plus <strong><code>22. Projects Master</code></strong>. The bot reads and writes exclusively here. Clients never see this spreadsheet.</p><hr><h2 id="two-spreadsheet-architecture" tabindex="-1">Two-spreadsheet architecture <a class="header-anchor" href="#two-spreadsheet-architecture" aria-label="Permalink to &quot;Two-spreadsheet architecture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Spreadsheet</th><th>Purpose</th><th>Who accesses it</th></tr></thead><tbody><tr><td><strong>Database sheet</strong></td><td>All operational data — tabs 01–14 + 22</td><td>Bot (service account) only</td></tr><tr><td><strong>Reporting sheet</strong></td><td>Human-facing dashboards</td><td>Clients and owners (no bot access)</td></tr></tbody></table><p>The reporting sheet imports data from the database sheet via <code>IMPORTRANGE</code>. The bot never reads or writes the reporting sheet.</p><hr><h2 id="the-schema-contract" tabindex="-1">The schema contract <a class="header-anchor" href="#the-schema-contract" aria-label="Permalink to &quot;The schema contract&quot;">​</a></h2><p><strong>Column order is the contract.</strong> The bot reads every sheet by positional index (<code>row[0]</code>, <code>row[1]</code>, etc.) — not by column name. This means:</p><ul><li><strong>Never reorder columns</strong> — even one shift breaks all reads for that sheet</li><li><strong>Never rename a sheet tab</strong> — tab names are string literals throughout the code</li><li><strong>Never insert a column in the middle</strong> — only append at the end</li><li><strong>Adding a column at the end is safe</strong></li></ul><p>If you need to make a schema change, it requires four simultaneous updates:</p><ol><li>The Google Sheet itself</li><li>The schema documentation</li><li>The column-offset code in <code>mcp-server.js</code></li><li>The test fixtures in <code>tests/mcp-routes.test.js</code></li></ol><hr><h2 id="foreign-key-relationships" tabindex="-1">Foreign key relationships <a class="header-anchor" href="#foreign-key-relationships" aria-label="Permalink to &quot;Foreign key relationships&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>03. Users ──┬── user_id ──→ 01. Time Entries</span></span>
<span class="line"><span>            ├── user_id ──→ 07. Budgets</span></span>
<span class="line"><span>            ├── pm_user_id → 02. Projects</span></span>
<span class="line"><span>            ├── discipline_id → 08. Disciplines</span></span>
<span class="line"><span>            ├── created_by ──→ 07. Budgets</span></span>
<span class="line"><span>            ├── user_id ──→ 10. Pending_PTO</span></span>
<span class="line"><span>            └── affected_user_id → 11. Unresolved_Items</span></span>
<span class="line"><span></span></span>
<span class="line"><span>02. Projects ┬── project_id → 01. Time Entries</span></span>
<span class="line"><span>             ├── project_id → 06. Project_Tasks</span></span>
<span class="line"><span>             ├── project_id → 07. Budgets</span></span>
<span class="line"><span>             ├── client_id → 04. Clients</span></span>
<span class="line"><span>             ├── parent_project_id → 02. Projects (self-ref, sprints)</span></span>
<span class="line"><span>             └── affected_project_id → 11. Unresolved_Items</span></span>
<span class="line"><span></span></span>
<span class="line"><span>04. Clients ──── client_id → 02. Projects</span></span>
<span class="line"><span></span></span>
<span class="line"><span>05. Tasks ──┬── task_id ──→ 01. Time Entries</span></span>
<span class="line"><span>            ├── task_id ──→ 06. Project_Tasks</span></span>
<span class="line"><span>            └── task_id ──→ 07. Budgets</span></span>
<span class="line"><span></span></span>
<span class="line"><span>22. Projects Master ── project_name →→ 02. Projects.name  (string join, not ID)</span></span></code></pre></div><hr><h2 id="tab-summary" tabindex="-1">Tab summary <a class="header-anchor" href="#tab-summary" aria-label="Permalink to &quot;Tab summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th><th>Key operations</th></tr></thead><tbody><tr><td><code>01. Time Entries</code></td><td>Every logged hour</td><td>Append, edit, delete</td></tr><tr><td><code>02. Projects</code></td><td>Project definitions</td><td>Append, update various cells</td></tr><tr><td><code>03. Users</code></td><td>Team members</td><td>Append, update role/status</td></tr><tr><td><code>04. Clients</code></td><td>Client organisations</td><td>Append</td></tr><tr><td><code>05. Tasks</code></td><td>Work categories</td><td>Append</td></tr><tr><td><code>06. Project_Tasks</code></td><td>Tasks enabled per project</td><td>Append (enable), delete (disable)</td></tr><tr><td><code>07. Budgets</code></td><td>Per-person hour envelopes</td><td>Append, update hours/status</td></tr><tr><td><code>08. Disciplines</code></td><td>Functional roles</td><td>Append</td></tr><tr><td><code>09. Conversations</code></td><td>24hr chat history</td><td>Append</td></tr><tr><td><code>10. Pending_PTO</code></td><td>Time off requests</td><td>Append, update status</td></tr><tr><td><code>11. Unresolved_Items</code></td><td>Flagged operational issues</td><td>Append, update status</td></tr><tr><td><code>12. Company_Calendar</code></td><td>Holidays and events</td><td>Append, delete</td></tr><tr><td><code>13. Rate_History</code></td><td>Hourly cost per person (versioned)</td><td>Append only</td></tr><tr><td><code>14. Liabilities</code></td><td>Vendor payment commitments</td><td>Append, update status</td></tr><tr><td><code>22. Projects Master</code></td><td>Financial metadata per project</td><td>Append (on create)</td></tr></tbody></table><p>See <a href="/vera-docs/reference/schema/sheets.html">All Sheets</a> for the complete column-by-column reference.</p><hr><h2 id="id-strategy" tabindex="-1">ID strategy <a class="header-anchor" href="#id-strategy" aria-label="Permalink to &quot;ID strategy&quot;">​</a></h2><p>All IDs follow the same pattern:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>new_id = MAX(existing ids in sheet) + 1</span></span></code></pre></div><p>IDs are <strong>permanent and sequential</strong> — never reused, even when records are deleted. This ensures time entry <code>#42</code> always refers to the same entry, enabling reliable audit trails and edit/delete operations via natural language.</p><hr><h2 id="write-ahead-log-wal" tabindex="-1">Write-Ahead Log (WAL) <a class="header-anchor" href="#write-ahead-log-wal" aria-label="Permalink to &quot;Write-Ahead Log (WAL)&quot;">​</a></h2><p>VERA uses a Write-Ahead Log pattern to handle the Google Sheets read-after-write race condition. After writing to a sheet, the new row is cached in memory so that an immediate read returns the correct data — even before Google&#39;s backend has propagated the write.</p><p>Three sheets currently have WAL protection:</p><ul><li><strong>Budgets</strong> (<code>07. Budgets</code>) — new envelopes, updates, and cancellations are visible immediately after write</li><li><strong>Conversations</strong> (<code>09. Conversations</code>) — ensures conversational context is available for immediate follow-up replies</li><li><strong>Time Entries</strong> (<code>01. Time Entries</code>) — newly logged, edited, or deleted entries are reflected in project status queries within seconds</li></ul><p>This is why you don&#39;t see &quot;just logged but not showing up&quot; issues despite Google Sheets&#39; eventual consistency model.</p>`,30)])])}const m=t(r,[["render",d]]);export{u as __pageData,m as default};
